```cs

void Start()
{
// 开启多点触摸
Input.multiTouchEnabled = true;
}
void Update()
{
// 判断单点触摸
if (Input.touchCount == 1)
{
// 触摸对象
Touch touch = Input.touches[0];
// 触摸位置
Debug._Log_(touch.position);
// 触摸阶段
switch (touch.phase)
{
case TouchPhase._Began_:
// 开始触摸
break;
case TouchPhase._Moved_:
// 移动触摸
break;
case TouchPhase._Stationary_:
// 触摸静止
break;
case TouchPhase._Ended_:
// 触摸结束
break;
case TouchPhase._Canceled_:
// 因为其他事件打断
break;
}
}
// 判断多点触摸
if (Input.touchCount >= 2)
{
foreach (Touch touch in Input.touches)
{   }
}
}
```

